import os
import sqlite3
import sys

sys.path.insert(0, os.getcwd())
from src.api import handle_import
from src.repository import initialize, list_contacts
from src.service import import_contacts

for isolation_level in ('', None):
    c = sqlite3.connect(':memory:', isolation_level=isolation_level)
    initialize(c)
    assert handle_import(c, {'contacts': [
        {'email': ' A@B ', 'name': ' Alice '},
    ]}) == {'inserted': 1, 'updated': 0}
    assert list_contacts(c) == [('a@b', 'Alice')]
    assert import_contacts(c, [{'email': 'a@b', 'name': 'Alice'},
                               {'email': 'c@d', 'name': 'Carol'}]) == {
                                   'inserted': 1, 'updated': 1}
    assert import_contacts(c, []) == {'inserted': 0, 'updated': 0}
    before = list_contacts(c)
    invalid_rows = [None, {}, {'email': 'x@y', 'name': 'X', 'extra': 1},
                    {'email': 1, 'name': 'X'}, {'email': 'x@y', 'name': None}]
    invalid_rows += [{'email': email, 'name': 'X'} for email in
                     ('@b', 'a@', 'a@@b', 'ab', 'a @b', 'a@\tb')]
    invalid_rows += [{'email': 'x@y', 'name': '  '}]
    for row in invalid_rows:
        try:
            import_contacts(c, [{'email': 'new@email', 'name': 'New'}, row])
        except ValueError:
            pass
        else:
            raise AssertionError('Invalid row accepted')
        assert list_contacts(c) == before
    try:
        import_contacts(c, [{'email': 'X@Y', 'name': 'X'},
                            {'email': ' x@y ', 'name': 'Y'}])
    except ValueError:
        pass
    else:
        raise AssertionError('Duplicate accepted')
    for payload in (None, [], {}, {'contacts': None}, {'contacts': [], 'extra': 1}):
        try:
            handle_import(c, payload)
        except ValueError:
            pass
        else:
            raise AssertionError('Invalid envelope accepted')
    c.execute("""CREATE TRIGGER fail_import BEFORE INSERT ON contacts
                 WHEN NEW.email = 'fail@test'
                 BEGIN SELECT RAISE(ABORT, 'failure'); END""")
    try:
        import_contacts(c, [{'email': 'a@b', 'name': 'Changed'},
                            {'email': 'new@test', 'name': 'New'},
                            {'email': 'fail@test', 'name': 'Fail'}])
    except sqlite3.DatabaseError:
        pass
    else:
        raise AssertionError('Database failure expected')
    assert list_contacts(c) == before
    assert not c.in_transaction
    c.close()
